<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Falling Sand — CA Sandbox</title>
<style>
  :root{
    --bg:#0b0d12;
    --panel:#151924;
    --panel2:#1c2230;
    --line:#2a3244;
    --txt:#e6ebf5;
    --dim:#8b95ab;
    --sand:#d9b166;
    --water:#3d7fd6;
    --wall:#7b8496;
    --acid:#8ef03c;
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0}
  body{
    background:radial-gradient(1200px 700px at 50% -10%,#161c2a 0%,var(--bg) 60%);
    color:var(--txt);
    font:14px/1.45 ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    min-height:100vh;
    display:flex;align-items:center;justify-content:center;
    padding:24px 12px 34px;
  }
  .app{
    width:min(620px,100%);
    display:flex;flex-direction:column;align-items:center;gap:14px;
  }
  header{text-align:center}
  h1{
    margin:0;font-size:20px;letter-spacing:.14em;text-transform:uppercase;
    font-weight:700;
    background:linear-gradient(90deg,var(--sand),var(--acid),var(--water));
    -webkit-background-clip:text;background-clip:text;color:transparent;
  }
  .sub{color:var(--dim);font-size:12px;margin-top:4px}
  .stage{
    padding:10px;border-radius:14px;
    background:linear-gradient(180deg,#1a2130,#12161f);
    border:1px solid var(--line);
    box-shadow:0 18px 50px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.04);
  }
  canvas#sand{
    display:block;
    width:480px;height:480px;
    background:#10131c;
    border-radius:8px;
    image-rendering:pixelated;
    image-rendering:crisp-edges;
    cursor:crosshair;
    touch-action:none;
  }
  .row{
    display:flex;flex-wrap:wrap;gap:8px;justify-content:center;align-items:center;
    width:100%;
  }
  button{
    -webkit-appearance:none;appearance:none;
    font:inherit;font-weight:600;
    color:var(--txt);
    background:var(--panel);
    border:1px solid var(--line);
    border-radius:10px;
    padding:9px 14px;
    cursor:pointer;
    display:inline-flex;align-items:center;gap:8px;
    transition:transform .06s ease,background .15s,border-color .15s,box-shadow .15s;
    user-select:none;
  }
  button:hover{background:var(--panel2);border-color:#3a465e}
  button:active{transform:translateY(1px)}
  button .dot{
    width:12px;height:12px;border-radius:3px;
    background:var(--c,#666);
    box-shadow:0 0 8px var(--c,#666);
    flex:none;
  }
  button.mat[aria-pressed="true"]{
    border-color:var(--c);
    background:linear-gradient(180deg,rgba(255,255,255,.07),rgba(255,255,255,.02)) ,var(--panel2);
    box-shadow:0 0 0 1px var(--c) inset,0 6px 18px rgba(0,0,0,.4);
  }
  #clear{border-color:#4a2530;background:#241820}
  #clear:hover{background:#2e1e27;border-color:#7a3b4c}
  .tools{
    display:flex;gap:10px;align-items:center;flex-wrap:wrap;justify-content:center;
    background:var(--panel);border:1px solid var(--line);border-radius:12px;
    padding:8px 12px;
  }
  label.slider{display:flex;align-items:center;gap:8px;color:var(--dim);font-size:12px}
  input[type=range]{width:110px;accent-color:var(--acid)}
  .stats{color:var(--dim);font-size:12px;font-variant-numeric:tabular-nums;text-align:center}
  .stats b{color:var(--txt);font-weight:600}
  kbd{
    background:#111622;border:1px solid var(--line);border-bottom-width:2px;
    border-radius:5px;padding:1px 5px;font-size:11px;color:var(--dim)
  }
</style>
</head>
<body>
<div class="app">
  <header>
    <h1>Falling&nbsp;Sand</h1>
    <div class="sub">Drag on the canvas to paint · <kbd>1</kbd>–<kbd>5</kbd> materials · <kbd>Space</kbd> pause · <kbd>C</kbd> clear</div>
  </header>

  <div class="stage">
    <canvas id="sand" width="480" height="480"></canvas>
  </div>

  <div class="row">
    <button class="mat" id="mat-sand"  style="--c:var(--sand)"  aria-pressed="true"><span class="dot"></span>Sand</button>
    <button class="mat" id="mat-water" style="--c:var(--water)" aria-pressed="false"><span class="dot"></span>Water</button>
    <button class="mat" id="mat-wall"  style="--c:var(--wall)"  aria-pressed="false"><span class="dot"></span>Wall</button>
    <button class="mat" id="mat-acid"  style="--c:var(--acid)"  aria-pressed="false"><span class="dot"></span>Acid</button>
    <button class="mat" id="mat-empty" style="--c:#3b4256"      aria-pressed="false"><span class="dot"></span>Eraser</button>
  </div>

  <div class="row">
    <div class="tools">
      <button id="pause">⏸ Pause</button>
      <button id="stepBtn">⏭ Step</button>
      <label class="slider">Brush <input id="brush" type="range" min="1" max="10" value="3"><span id="brushVal">3</span></label>
      <label class="slider">Speed <input id="speed" type="range" min="1" max="4" value="1"><span id="speedVal">1×</span></label>
    </div>
    <button id="clear">🗑 Clear</button>
  </div>

  <div class="stats" id="stats"></div>
</div>

<script>
(function(){
  "use strict";

  /* ---------------- grid / materials ---------------- */
  const W = 120, H = 120;                 // 120 x 120 cells (>= 80x80)
  const EMPTY=0, SAND=1, WATER=2, WALL=3, ACID=4;
  const NAMES = ["empty","sand","water","wall","acid"];
  const IDS   = {empty:EMPTY, sand:SAND, water:WATER, wall:WALL, acid:ACID};

  const grid  = new Uint8Array(W*H);
  const moved = new Uint8Array(W*H);
  const noise = new Uint8Array(W*H);
  for (let i=0;i<noise.length;i++) noise[i] = (Math.random()*256)|0;

  const idx  = (x,y) => y*W + x;
  const inb  = (x,y) => x>=0 && x<W && y>=0 && y<H;
  const rnd  = Math.random;

  function swapCells(a,b){
    const t = grid[a]; grid[a] = grid[b]; grid[b] = t;
    moved[a] = 1; moved[b] = 1;
  }

  /* ---------------- rules ---------------- */

  // SAND: straight down, sinks through liquids, otherwise diagonal slide.
  function updSand(x,y,i){
    if (y+1 >= H) return;                       // bottom row = solid boundary
    const bi = idx(x,y+1), b = grid[bi];

    if (b === EMPTY){ swapCells(i,bi); return; }

    if (b === WATER || b === ACID){
      // The liquid we displace must escape *locally*. It may only rise into the
      // cell the grain just vacated when that cell is not part of a sand column,
      // so liquid can never be pumped upward through a falling stream.
      const above = (y > 0) ? grid[idx(x,y-1)] : EMPTY;
      if (above !== SAND){ swapCells(i,bi); return; }

      const d = rnd() < 0.5 ? -1 : 1;
      const cand = [[x+d,y+1],[x-d,y+1],[x+d,y],[x-d,y]];
      for (let k=0;k<cand.length;k++){
        const cx = cand[k][0], cy = cand[k][1];
        if (cx < 0 || cx >= W || cy < 0 || cy >= H) continue;
        const ci = idx(cx,cy);
        if (grid[ci] === EMPTY){
          grid[ci] = b;    moved[ci] = 1;       // liquid squeezes out sideways
          grid[bi] = SAND; moved[bi] = 1;       // grain takes its place
          grid[i]  = EMPTY;
          return;
        }
      }
      return;                                   // nowhere to go -> rest
    }

    // blocked below (sand / wall): try diagonals, random order
    const d = rnd() < 0.5 ? -1 : 1;
    for (let s=0;s<2;s++){
      const nx = x + (s===0 ? d : -d);
      if (nx < 0 || nx >= W) continue;
      const ni = idx(nx,y+1);
      if (grid[ni] === EMPTY){ swapCells(i,ni); return; }
    }
  }

  // WATER / ACID motion: fall, fall diagonally, else spread sideways.
  function updLiquid(x,y,i){
    if (y+1 < H){
      const bi = idx(x,y+1);
      if (grid[bi] === EMPTY){ swapCells(i,bi); return; }
      const d = rnd() < 0.5 ? -1 : 1;
      for (let s=0;s<2;s++){
        const nx = x + (s===0 ? d : -d);
        if (nx < 0 || nx >= W) continue;
        const ni = idx(nx,y+1);
        if (grid[ni] === EMPTY){ swapCells(i,ni); return; }
      }
    }
    const d2 = rnd() < 0.5 ? -1 : 1;
    for (let s=0;s<2;s++){
      const nx = x + (s===0 ? d2 : -d2);
      if (nx < 0 || nx >= W) continue;
      const ni = idx(nx,y);
      if (grid[ni] === EMPTY){ swapCells(i,ni); return; }
    }
  }

  // ACID: corrodes sand / wall below or beside, then moves like water.
  function updAcid(x,y,i){
    const d = rnd() < 0.5 ? -1 : 1;
    const cand = [[x,y+1],[x+d,y],[x-d,y]];
    for (let k=0;k<cand.length;k++){
      const cx = cand[k][0], cy = cand[k][1];
      if (cx < 0 || cx >= W || cy < 0 || cy >= H) continue;
      const ci = idx(cx,cy), t = grid[ci];
      if (t === SAND || t === WALL){
        const p = (t === WALL) ? 0.35 : 0.85;
        if (rnd() < p){
          grid[ci] = EMPTY; moved[ci] = 1;      // dissolved (walls erode too)
          if (rnd() < 0.12){ grid[i] = EMPTY; return; } // acid sometimes spent
        }
        break;
      }
    }
    updLiquid(x,y,i);
  }

  // One simulation step: bottom row upward -> max one cell of travel per step.
  function step(){
    moved.fill(0);
    for (let y = H-1; y >= 0; y--){
      const leftFirst = rnd() < 0.5;
      for (let k = 0; k < W; k++){
        const x = leftFirst ? k : (W-1-k);
        const i = idx(x,y);
        if (moved[i]) continue;
        const t = grid[i];
        if (t === EMPTY || t === WALL) continue;
        if (t === SAND) updSand(x,y,i);
        else if (t === WATER) updLiquid(x,y,i);
        else if (t === ACID) updAcid(x,y,i);
      }
    }
  }

  /* ---------------- rendering ---------------- */
  const canvas = document.getElementById("sand");
  const ctx = canvas.getContext("2d");
  const off = document.createElement("canvas");
  off.width = W; off.height = H;
  const octx = off.getContext("2d");
  const img = octx.createImageData(W,H);
  const counts = [0,0,0,0,0];

  function draw(){
    const data = img.data;
    counts[0]=counts[1]=counts[2]=counts[3]=counts[4]=0;
    for (let i=0;i<W*H;i++){
      const t = grid[i], n = noise[i];
      counts[t]++;
      let r,g,b;
      switch(t){
        case SAND:  r=214+((n%25)-12); g=176+((n%21)-10); b= 98+((n%19)-9); break;
        case WATER: r= 46+((n%13)-6);  g=118+((n%17)-8);  b=214+((n%15)-7); break;
        case WALL:  r=112+((n%17)-8);  g=122+((n%17)-8);  b=142+((n%17)-8); break;
        case ACID:  r=132+((n%29)-14); g=238+((n%15)-7);  b= 62+((n%25)-12); break;
        default:    r=16+((n%7)-3);    g=19+((n%7)-3);    b=28+((n%9)-4);    break;
      }
      const p = i*4;
      data[p]=r; data[p+1]=g; data[p+2]=b; data[p+3]=255;
    }
    octx.putImageData(img,0,0);
    ctx.imageSmoothingEnabled = false;
    ctx.clearRect(0,0,canvas.width,canvas.height);
    ctx.drawImage(off,0,0,canvas.width,canvas.height);
  }

  const statsEl = document.getElementById("stats");
  function updStats(){
    statsEl.innerHTML =
      "grid <b>"+W+"×"+H+"</b> &nbsp;·&nbsp; sand <b>"+counts[SAND]+
      "</b> &nbsp;·&nbsp; water <b>"+counts[WATER]+
      "</b> &nbsp;·&nbsp; wall <b>"+counts[WALL]+
      "</b> &nbsp;·&nbsp; acid <b>"+counts[ACID]+"</b>";
  }

  /* ---------------- painting ---------------- */
  let current = SAND;
  let brush = 3;
  let painting = false;
  let lastCell = null;

  function paintDisc(cx,cy,mat,r){
    const r2 = r*r;
    for (let dy=-r; dy<=r; dy++){
      for (let dx=-r; dx<=r; dx++){
        if (dx*dx + dy*dy > r2) continue;
        const x = cx+dx, y = cy+dy;
        if (!inb(x,y)) continue;
        grid[idx(x,y)] = mat;
      }
    }
  }
  function paintLine(x0,y0,x1,y1,mat,r){
    const steps = Math.max(Math.abs(x1-x0), Math.abs(y1-y0));
    if (steps === 0){ paintDisc(x1,y1,mat,r); return; }
    for (let s=0;s<=steps;s++){
      const t = s/steps;
      paintDisc(Math.round(x0+(x1-x0)*t), Math.round(y0+(y1-y0)*t), mat, r);
    }
  }
  function toCell(ev){
    const r = canvas.getBoundingClientRect();
    const x = Math.floor((ev.clientX - r.left) / r.width  * W);
    const y = Math.floor((ev.clientY - r.top ) / r.height * H);
    return [Math.max(0,Math.min(W-1,x)), Math.max(0,Math.min(H-1,y))];
  }

  canvas.addEventListener("pointerdown", ev=>{
    ev.preventDefault();
    canvas.setPointerCapture(ev.pointerId);
    painting = true;
    const c = toCell(ev); lastCell = c;
    paintDisc(c[0],c[1],current,brush);
    draw();
  });
  canvas.addEventListener("pointermove", ev=>{
    if (!painting) return;
    const c = toCell(ev);
    paintLine(lastCell[0],lastCell[1],c[0],c[1],current,brush);
    lastCell = c;
  });
  const stopPaint = ()=>{ painting = false; };
  canvas.addEventListener("pointerup", stopPaint);
  canvas.addEventListener("pointercancel", stopPaint);
  canvas.addEventListener("pointerleave", ()=>{ /* keep capture-based drag */ });
  window.addEventListener("blur", stopPaint);
  // mouse-only fallback so plain mouse events (synthetic tests) also paint
  canvas.addEventListener("mousedown", ev=>{
    if (painting) return;
    painting = true;
    const c = toCell(ev); lastCell = c;
    paintDisc(c[0],c[1],current,brush); draw();
  });
  canvas.addEventListener("mousemove", ev=>{
    if (!painting || !lastCell) return;
    const c = toCell(ev);
    paintLine(lastCell[0],lastCell[1],c[0],c[1],current,brush);
    lastCell = c;
  });
  window.addEventListener("mouseup", stopPaint);

  /* ---------------- controls ---------------- */
  const matButtons = {
    "mat-sand":SAND, "mat-water":WATER, "mat-wall":WALL,
    "mat-acid":ACID, "mat-empty":EMPTY
  };
  function selectMat(id){
    current = matButtons[id];
    Object.keys(matButtons).forEach(k=>{
      document.getElementById(k).setAttribute("aria-pressed", String(k===id));
    });
  }
  Object.keys(matButtons).forEach(id=>{
    document.getElementById(id).addEventListener("click", ()=>selectMat(id));
  });

  const clearBtn = document.getElementById("clear");
  clearBtn.addEventListener("click", ()=>{ grid.fill(EMPTY); draw(); updStats(); });

  let paused = false;
  const pauseBtn = document.getElementById("pause");
  pauseBtn.addEventListener("click", ()=>{
    paused = !paused;
    pauseBtn.textContent = paused ? "▶ Play" : "⏸ Pause";
  });
  document.getElementById("stepBtn").addEventListener("click", ()=>{ step(); draw(); updStats(); });

  const brushInput = document.getElementById("brush"), brushVal = document.getElementById("brushVal");
  brushInput.addEventListener("input", ()=>{ brush = +brushInput.value; brushVal.textContent = brush; });

  let speed = 1;
  const speedInput = document.getElementById("speed"), speedVal = document.getElementById("speedVal");
  speedInput.addEventListener("input", ()=>{ speed = +speedInput.value; speedVal.textContent = speed+"×"; });

  window.addEventListener("keydown", ev=>{
    const k = ev.key.toLowerCase();
    if (k === "1") selectMat("mat-sand");
    else if (k === "2") selectMat("mat-water");
    else if (k === "3") selectMat("mat-wall");
    else if (k === "4") selectMat("mat-acid");
    else if (k === "5") selectMat("mat-empty");
    else if (k === "c"){ grid.fill(EMPTY); draw(); updStats(); }
    else if (k === " "){ ev.preventDefault(); pauseBtn.click(); }
  });

  /* ---------------- main loop ---------------- */
  let acc = 0;
  function frame(){
    if (painting && lastCell) paintDisc(lastCell[0],lastCell[1],current,brush);
    if (!paused){ for (let s=0;s<speed;s++) step(); }
    draw();
    if (++acc % 10 === 0) updStats();
    requestAnimationFrame(frame);
  }
  draw(); updStats();
  requestAnimationFrame(frame);

  /* ---------------- public API ---------------- */
  window.sim = {
    w: W,
    h: H,
    tick(n){
      n = (n === undefined || n === null) ? 1 : (n|0);
      for (let k=0;k<n;k++) step();
      return this;
    },
    get(x,y){
      x |= 0; y |= 0;
      if (!inb(x,y)) return "wall";           // edges / floor are solid
      return NAMES[grid[idx(x,y)]];
    },
    set(x,y,material){
      x |= 0; y |= 0;
      const v = IDS[String(material).toLowerCase()];
      if (v === undefined || !inb(x,y)) return false;
      grid[idx(x,y)] = v;
      return true;
    },
    clear(){ grid.fill(EMPTY); return this; },
    render(){ draw(); updStats(); },
    step(){ step(); }
  };
})();
</script>
</body>
</html>
